UPDATE content SET overview_uk = v.overview_uk, has_uk_translation = true FROM (VALUES
  (7148, 'У старому забутому місці жив злий і підступний Кощій Безсмертний. Він доживав свої дні серед сірих туманів і лихих завивань невідомих тварин. Уже не було чарівного кота, який співав пісні та розповідав вірші, русалка померла, як і багато інших казкових персонажів. Залишився лише він — нещасний старий.')
) AS v(id, overview_uk) WHERE content.id = v.id;
